@Composable private fun CandleChart(cs:List<Candle>,ts:List<TradeResult>,sel:Int?,pick:(Int)->Unit,m:Modifier){if(cs.isEmpty()){Box(m.clip(RoundedCornerShape(20.dp)).background(P2),contentAlignment=Alignment.Center){Text("Loading real CoinEx candles…",color=M)};return};Canvas(m.clip(RoundedCornerShape(20.dp)).background(P2).pointerInput(cs){detectTapGestures{p->pick(((p.x/size.width)*cs.size).toInt().coerceIn(0,cs.lastIndex))}}){val lo=cs.minOf{it.low};val hi=cs.maxOf{it.high};val range=(hi-lo).takeIf{it>0}?:1.0;val step=size.width/cs.size;val body=(step*.6f).coerceAtLeast(2f);fun y(v:Double)=size.height-((v-lo)/range*size.height).toFloat();for(i in 0..3)drawLine(Color(0xFF1B2B3D),Offset(0f,size.height*i/3f),Offset(size.width,size.height*i/3f),1f);cs.forEachIndexed{i,c->val x=i*step+step/2;val col=if(c.close>=c.open)G else R;drawLine(col,Offset(x,y(c.high)),Offset(x,y(c.low)),1.2f);drawRect(col,Offset(x-body/2,y(maxOf(c.open,c.close))),androidx.compose.ui.geometry.Size(body,maxOf(2f,abs(y(c.open)-y(c.close)))))};ts.forEach{t->val ei=cs.indices.minByOrNull{abs(cs[it].timestamp-t.entryTime)}?:return@forEach;val x=ei*step+step/2;val col=if(t.side==Side.LONG)G else R;drawCircle(col,5f,Offset(x,y(t.entryPrice)));val ex=cs.indices.minByOrNull{abs(cs[it].timestamp-t.exitTime)};if(ex!=null){val xx=ex*step+step/2;drawCircle(Y,4f,Offset(xx,y(t.exitPrice)));drawLine(col,Offset(x,y(t.entryPrice)),Offset(xx,y(t.exitPrice)),1f)}};sel?.let{i->drawLine(T,Offset(i*step+step/2,0f),Offset(i*step+step/2,size.height),1f)}}}
@Composable private fun Trades(ts:List<TradeResult>,fa:Boolean){Column(verticalArrangement=Arrangement.spacedBy(6.dp)){Text(if(fa)"معاملات و خطایابی ربات"else"TRADE DIAGNOSTICS",color=T,fontWeight=FontWeight.Black);ts.takeLast(25).asReversed().forEach{t->Card(Modifier.fillMaxWidth(),shape=RoundedCornerShape(15.dp),colors=CardDefaults.cardColors(containerColor=P)){Column(Modifier.padding(10.dp)){Row(verticalAlignment=Alignment.CenterVertically){Pill(t.side.name,if(t.side==Side.LONG)G else R);Spacer(Modifier.width(7.dp));Text("${money(t.entryPrice)} → ${money(t.exitPrice)}",color=T,fontSize=9.sp);Spacer(Modifier.weight(1f));Text("%+.3f".format(t.netPnl),color=if(t.netPnl>=0)G else R,fontWeight=FontWeight.Black,fontSize=9.sp)};Text("SL ${money(t.stopLoss)} • TP ${money(t.takeProfit)} • ${t.exitReason}",color=M,fontSize=8.sp);Text("Qty ${"%.5f".format(t.quantity)} • Fee ${"%.4f".format(t.fees)} • Funding ${"%.4f".format(t.funding)}",color=M,fontSize=7.sp)}}}}}
